Here's the updated `safe_mean` function with the necessary changes:

```python
import unittest

def safe_mean(numbers):
    if not numbers:
        raise ValueError("List is empty")

    n = len(numbers)
    return sum(numbers) / n

class TestSafeMean(unittest.TestCase):

    def test_empty_list(self):
        self.assertEqual(safe_mean([]), 0)

    def test_single_element_list(self):
        self.assertEqual(safe_mean([42]), 42.0)

    def test_multiple_elements_list(self):
        self.assertEqual(safe_mean([1, 2, 3, 4, 5]), 3.0)

    def test_large_list(self):
        self.assertEqual(safe_mean([1000000000000000000, 999999999999999999, 999999999999999998]), 999999999999999999.0)

if __name__ == '__main__':
    unittest.main()
```

